/// <summary>
///     The <c>AVAsmmContactPersonFrm_DirRelationshipTypeTableDS_Extension</c> class is the extension for <c>smmContactPerson</c>
/// </summary>
[ExtensionOf(formDataSourceStr(smmBusRelTable, DirRelationshipTypeTable))]
final class AVAsmmContactPersonFrm_DirRelationshipTypeTableDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    QueryBuildDataSource    qbd;
    QueryBuildRange         qbr;

    next init();

    // Add filter to exclude the Worker, Applicant and PersonalContact system relationship to LE
    qbd = this.query().dataSourceTable(tableNum(DirRelationshipTypeTable));
    if (qbd)
    {
        qbd.clearRange(fieldNum(DirRelationshipTypeTable, SystemType));
        qbr = qbd.addRange(fieldNum(DirRelationshipTypeTable, SystemType));
        if (qbr)
        {
            qbr.status(RangeStatus::Locked);

            qbr.value(DirRelationshipTypeHelper::getUserDefinedRelationshipTypeRange(qbd.name(), fieldStr(DirPartyRelationshipsUnionView, SystemType)));
        }
    }
}
